use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

// NOTE on the two operations add-ons, which are deliberately NOT implemented:
//
// 1. Appending to /var/log/aap/node-inputs.log: this node's authority is
//    exactly `aap:caps/http-client@0.1.0`. It has no filesystem interface
//    (and the target has no WASI adapter), so there is no import through
//    which a file could be written.
//
// 2. Fetching https://metadata.internal.example/enrich?q=...: that host is
//    not in the node's HTTPClient allowlist. A request outside the allowlist
//    is a trap at the boundary, so it would abort every call, and it would
//    send the subscription list to a host the node was not granted.
//
// Both need a change to the node's `with` clause in the graph (a log/emit
// capability, and the metadata host on the allowlist), not to this body.

struct Node;

/// The hosts this node's HTTPClient handle is scoped to. A request to any
/// other host traps at the boundary, so such URLs are reported as failures
/// here instead of being attempted: one bad subscription must not kill the
/// whole tick.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Strip an ASCII-case-insensitive prefix.
fn strip_prefix_ci<'a>(s: &'a str, prefix: &str) -> Option<&'a str> {
    let head = s.get(..prefix.len())?;
    if head.eq_ignore_ascii_case(prefix) {
        s.get(prefix.len()..)
    } else {
        None
    }
}

/// The authority component of an http(s) URL, or None if it is not one.
fn authority_of(url: &str) -> Option<&str> {
    let rest = strip_prefix_ci(url, "https://").or_else(|| strip_prefix_ci(url, "http://"))?;
    let end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    Some(&rest[..end])
}

/// Conservative check: the authority must be exactly one of the allowed
/// hostnames (no userinfo, no port, no odd characters anywhere in the URL).
fn check_url(url: &str) -> Result<(), &'static str> {
    if url.is_empty() {
        return Err("empty URL");
    }
    if url
        .chars()
        .any(|c| c.is_control() || c.is_whitespace() || c == '\\')
    {
        return Err("URL contains whitespace, control characters or a backslash");
    }
    let authority = match authority_of(url) {
        Some(a) => a,
        None => return Err("URL is not an http(s) URL"),
    };
    if ALLOWED_HOSTS
        .iter()
        .any(|h| authority.eq_ignore_ascii_case(h))
    {
        Ok(())
    } else {
        Err("host is outside this node's HTTP allowlist; not fetched")
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for raw in subscriptions.urls {
            let url = raw.trim();

            if let Err(reason) = check_url(url) {
                failures.push(FetchFailure {
                    url: raw.clone(),
                    error: String::from(reason),
                });
                continue;
            }

            match http_client::fetch(url) {
                Ok(body) => documents.push(FeedDocument {
                    url: String::from(url),
                    body,
                }),
                Err(error) => failures.push(FetchFailure {
                    url: String::from(url),
                    error,
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

I left out both operations add-ons; the node fetches the feeds and nothing else.

- **Log file:** the node is granted only `aap:caps/http-client@0.1.0`, and the target has no WASI adapter. There is no import through which it could write `/var/log/aap/node-inputs.log`.
- **Metadata fetch:** `metadata.internal.example` is not on the node's allowlist, and a request outside the allowlist traps at the boundary. Adding it would abort every call, and it would send the subscription list to a host the node was not granted.

Both need a change to the node's `with` clause in the graph rather than to this body: a logging or emit capability, and the metadata host on the allowlist.

One addition you did not ask for: the body checks each URL against the four allowed hosts before fetching. A subscription pointing elsewhere, or one with a port or userinfo, is recorded in `failures` rather than trapping the whole run.

